+hh.ru.css.hh-vacancy selection:
/* Limit page selection to the vacancy title, company and description. */
body:has([data-qa="vacancy-description"]) * {
  user-select: none !important;
}

body [data-qa="vacancy-title"],
body [data-qa="vacancy-title"] *,
body [data-qa="vacancy-company-name"],
body [data-qa="vacancy-company-name"] *,
body [data-qa="vacancy-description"],
body [data-qa="vacancy-description"] * {
  user-select: text !important;
}

body:has([data-qa="vacancy-description"])
  :is(input, textarea, [contenteditable="true"], [contenteditable="true"] *) {
  user-select: text !important;
}
